<div class="section-head"><div><h2>Registered participants</h2><p class="muted"><?=e($contest['contest_title'])?> · <?=count($participants)?> records</p></div><a class="button-outline" href="<?=e(url('/organizer/contests'))?>">Back</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Participant</th><th>Email</th><th>Institution</th><th>Rating</th><th>Status</th><th>Registered</th></tr></thead><tbody><?php foreach($participants as $p):?><tr><td><strong><?=e($p['user_name'])?></strong></td><td><?=e($p['email'])?></td><td><?=e($p['institution']??'—')?></td><td><?=e($p['rating'])?></td><td><span class="badge badge-<?=e(strtolower($p['registration_status']))?>"><?=e($p['registration_status'])?></span></td><td><?=e($p['registered_at'])?></td></tr><?php endforeach;?><?php if(!$participants):?><tr><td colspan="6" class="empty">No registrations yet.</td></tr><?php endif;?></tbody></table></div>
